 auto caller_doc=initial;if(mode==1)caller_doc.id="replacement-solid-color-document";if(mode==7)entry(caller_doc).parameters.at("a").literal=.7654321098765432;if(mode==8)entry(caller_doc).gradient->start_x.literal+=1;if(mode==9){entry(caller_doc).enabled_driver.reset();entry(caller_doc).enabled_expression=Expression{"true",1};}if(mode==10){auto& stack=caller_doc.objects.at("built").stack;stack.erase(std::remove_if(stack.begin(),stack.end(),[](const auto& e){return e.id=="fill";}),stack.end());auto removed=base;removed.apply({RemoveOperation{"built","fill"}},0);check(removed.document()==caller_doc,"Independent entire missing paint agrees canonical removal BEFORE Window");}if(mode==11){caller_doc.objects.erase("built");auto& roots=caller_doc.compositions.front().roots;roots.erase(std::remove(roots.begin(),roots.end(),"built"),roots.end());auto removed=base;removed.apply({DeleteObjects{{"built"}}},0);check(removed.document()==caller_doc,"Independent entire missing owner agrees canonical deletion BEFORE Window");}valid(caller_doc);Session replaced(caller_doc);Session caller=mode==3?committed:mode==4?active:mode==5||mode==6?cancelled:replaced;const Session loaded=mode==6?active:base;
